## Submitted testbench
```systemverilog
module tb;

  // Parameters
  localparam int CLK_PERIOD = 8;

  // DUT ports
  logic clk;
  logic rst;
  logic [15:0] prescale;
  logic [7:0] s_axis_tdata;
  logic s_axis_tvalid;
  logic s_axis_tready;
  logic [7:0] m_axis_tdata;
  logic m_axis_tvalid;
  logic m_axis_tready;
  logic rxd;
  logic txd;
  logic tx_busy;
  logic rx_busy;
  logic rx_overrun_error;
  logic rx_frame_error;

  // Drive m_axis_tready constantly
  initial m_axis_tready = 1'b1;

  // Instantiate DUT
  uart #(.DATA_WIDTH(8)) dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(txd),
    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  // Clock generation
  initial clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // Reset sequence
  initial begin
    rst = 1'b1;
    repeat (5) @(posedge clk);
    rst = 1'b0;
  end

  // Prescale value
  initial prescale = 16'd1;

  // Tie off unused UART inputs
  initial rxd = 1'b1;

  // Tie off status outputs (dummy)
  initial begin
    m_axis_tdata = 8'h0;
    m_axis_tvalid = 1'b0;
    rx_busy = 1'b0;
    rx_overrun_error = 1'b0;
    rx_frame_error = 1'b0;
  end

  // Task to send a frame
  task automatic send_frame(input [7:0] data);
    // Wait until s_axis_tready is high
    wait (s_axis_tready);
    // Drive data and tvalid for one cycle
    s_axis_tdata = data;
    s_axis_tvalid = 1'b1;
    @(posedge clk);
    s_axis_tvalid = 1'b0;
  endtask

  // Task to wait for tx_busy to go low
  task automatic wait_tx_busy_low;
    // Wait until tx_busy is low
    wait (!tx_busy);
  endtask

  // Main program
  initial begin
    // Allow a couple of cycles after reset
    repeat (2) @(posedge clk);

    // Send first frame (MSB=0, e.g., 8'h5A)
    send_frame(8'h5A);
    // Wait for busy to go low
    wait_tx_busy_low();
    // Wait 9 clock cycles (stop gap)
    repeat (9) @(posedge clk);

    // Send second frame
    send_frame(8'h5A);
    // Wait for busy to go low
    wait_tx_busy_low();
    // Wait 9 clock cycles
    repeat (9) @(posedge clk);

    // Send a dummy third frame to cause the falling edge that triggers coverage
    send_frame(8'h00);
    // Small extra wait before finishing
    repeat (2) @(posedge clk);
    $finish;
  end

endmodule
```

